name: CI

on:
  push:
    branches: [main]
  pull_request:
  workflow_dispatch:

permissions:
  contents: read

concurrency:
  group: ci-${{ github.ref }}
  cancel-in-progress: true

jobs:
  go:
    name: Go build / vet / test
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-go@v5
        with:
          go-version: '1.25'
          cache: true

      - name: Build
        run: go build ./...

      - name: Vet
        run: go vet ./...

      - name: Test
        run: go test ./...

      # Fails when the CLI, the TypeScript SDK, the OpenAPI catalog and the registered
      # server routes drift apart. The repo is kept at zero gaps.
      - name: API surface audit
        run: go run ./cmd/api-surface-audit

  web:
    name: Web lint / test / build
    runs-on: ubuntu-latest
    defaults:
      run:
        working-directory: web
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: '24'
          cache: npm
          cache-dependency-path: web/package-lock.json

      - name: Install
        run: npm ci

      - name: Lint
        run: npm run lint

      - name: Test
        run: npm test

      # `tsc -b && vite build` — also the type check for the SPA.
      - name: Build
        run: npm run build
# syntax=docker/dockerfile:1.7
FROM node:24-alpine AS web-build
WORKDIR /src/web

COPY web/package.json web/package-lock.json ./
RUN npm ci

COPY web/ ./
RUN npm run build

FROM golang:1.25-alpine AS build
WORKDIR /src

ENV CGO_ENABLED=0 \
    GOFLAGS=-trimpath \
    GO111MODULE=on

COPY go.mod go.sum ./
RUN go mod download

COPY . .
COPY --from=web-build /src/web/dist ./web/dist

ARG TARGETOS=linux
ARG TARGETARCH=amd64
# main.version 은 이 저장소에 없는 이름이라 링커가 조용히 무시하고 있었다 —
# 값이 들어가는 것처럼 보였을 뿐 어느 빌드인지 알 길이 없었다. 실제로 있는
# internal/buildinfo 에 새기고, 커밋과 빌드 시각도 함께 넣는다.
ARG VERSION=dev
ARG COMMIT=unknown
ARG BUILD_TIME=unknown
RUN GOOS=${TARGETOS} GOARCH=${TARGETARCH} \
    go build -trimpath -ldflags "-s -w \
      -X dataworks/internal/buildinfo.Version=${VERSION} \
      -X dataworks/internal/buildinfo.Commit=${COMMIT} \
      -X dataworks/internal/buildinfo.BuildTime=${BUILD_TIME}" \
    -o /out/dataworks ./cmd/dataworks && \
    mkdir -p /out/data

FROM gcr.io/distroless/static:nonroot AS runtime
ARG VERSION=dev
ARG COMMIT=unknown
ARG BUILD_TIME=unknown
LABEL org.opencontainers.image.title="Data Works" \
      org.opencontainers.image.description="Data Works API gateway and governance server" \
      org.opencontainers.image.source="https://github.com/hkjang/dataworks" \
      org.opencontainers.image.version="${VERSION}" \
      org.opencontainers.image.revision="${COMMIT}" \
      org.opencontainers.image.created="${BUILD_TIME}"
WORKDIR /app
USER nonroot:nonroot

COPY --chown=nonroot:nonroot --from=build /out/dataworks /app/dataworks
COPY --chown=nonroot:nonroot --from=build /out/data /data

ENV LISTEN_ADDR=:8080 \
    DB_DRIVER=sqlite \
    DB_DSN=/data/gateway.db \
    LOG_FALLBACK_PATH=/data/fallback.ndjson

VOLUME ["/data"]
EXPOSE 8080

ENTRYPOINT ["/app/dataworks"]
[CmdletBinding()]
param(
    [string]$Version,
    [string]$PrevVersion,
    [switch]$Edit  # update an existing release's notes instead of creating it (no asset upload)
)

$ErrorActionPreference = "Stop"

if (-not $Version) {
    throw "Version parameter is required. Example: pwsh -File scripts/gh_release.ps1 -Version vVERSION -PrevVersion vPREVIOUS"
}
if (-not $PrevVersion) {
    throw "PrevVersion parameter is required. Example: pwsh -File scripts/gh_release.ps1 -Version vVERSION -PrevVersion vPREVIOUS"
}

$repoRoot = Split-Path -Parent $PSScriptRoot
Set-Location $repoRoot

$cleanVer = $Version.TrimStart('v')

# Load changelog file
$changelogPath = Join-Path $PSScriptRoot "changelog.txt"
if (-not (Test-Path $changelogPath)) {
    throw "changelog.txt file is missing at $changelogPath"
}
$utf8 = [System.Text.Encoding]::UTF8
$changelogLines = [System.IO.File]::ReadAllLines($changelogPath, $utf8)

# Verify versions exist and extract all logs between Version and PrevVersion (exclusive)
$foundStart = $false
$foundEnd = $false
$extractedLogs = @()

foreach ($line in $changelogLines) {
    if ($line -match "^$Version`:") {
        $foundStart = $true
        $note = $line.Substring($line.IndexOf(':') + 1).Trim()
        if ($note) { $extractedLogs += $note }
        continue
    }

    if ($foundStart) {
        if ($line -match "^$PrevVersion`:") {
            $foundEnd = $true
            break
        }
        $extractedLogs += $line
    }
}

if (-not $foundStart) {
    throw "Target version $Version is not documented in scripts/changelog.txt."
}
if (-not $foundEnd) {
    throw "Previous version $PrevVersion is not documented in scripts/changelog.txt."
}

$targetChangelog = $extractedLogs -join "`r`n"

$notes = "## Data Works v" + $cleanVer + "`r`n`r`n"
$notes += [regex]::Unescape("### \uc8fc\uc694 \ubcc0\uacbd \uc0ac\ud56d`r`n")
$notes += $targetChangelog + "`r`n`r`n"

$notes += [regex]::Unescape("### \ubc30\ud3ec \ud30c\uc77c`r`n")
$notes += [regex]::Unescape("| \ud30c\uc77c | \uc124\uba85 |`r`n")
$notes += "|------|------|`r`n"
$notes += "| dataworks-v" + $cleanVer + [regex]::Unescape(".tar.gz | \uc624\ud504\ub77c\uc778 \uc801\uc7ac \uac00\ub2a5\ud55c Data Works Docker \uc774\ubbf8\uc9c0 (linux/amd64) |`r`n`r`n")

$notes += [regex]::Unescape("### \ube60\ub978 \uc2dc\uc791`r`n")
$notes += '```' + "bash`r`n"
$notes += [regex]::Unescape("# \uc774\ubbf8\uc9c0 \ub85c\ub4dc`r`n")
$notes += "gunzip -c dataworks-" + $Version + ".tar.gz | docker load`r`n`r`n"
$notes += [regex]::Unescape("# \uc2e4\ud589`r`n")
$notes += "docker run -d --name dataworks --restart=always \`r`n"
$notes += "  -p 8080:8080 \`r`n"
$notes += "  -e POSTGRES_DSN='postgres://dataworks:change-me@postgres:5432/dataworks?sslmode=disable' \`r`n"
$notes += "  -e BOOTSTRAP_ADMIN='admin@dataworks.local' \`r`n"
$notes += "  -e BOOTSTRAP_ADMIN_PASSWORD='change-me' \`r`n"
$notes += "  -e ENCRYPTION_KEY='replace-with-64-hex-characters' \`r`n"
$notes += "  dataworks:" + $Version + "`r`n"
$notes += '```'

$notesPath = Join-Path $repoRoot "release\release-notes.txt"
# Ensure the release directory exists
$releaseDir = Split-Path -Parent $notesPath
if (-not (Test-Path $releaseDir)) {
    New-Item -ItemType Directory -Path $releaseDir -Force | Out-Null
}

# Write as UTF-8 WITHOUT BOM via .NET so the GitHub release body has no leading BOM
# and is identical regardless of which PowerShell edition runs this script.
[System.IO.File]::WriteAllText($notesPath, $notes, (New-Object System.Text.UTF8Encoding($false)))

if ($Edit) {
    # Re-publish corrected notes for an already-created release (no asset re-upload).
    gh release edit $Version --repo hkjang/dataworks --notes-file $notesPath
} else {
    $assetPath = "release\dataworks-$Version.tar.gz"
    if (-not (Test-Path $assetPath)) {
        throw "Release asset is missing: $assetPath"
    }
    $assets = @($assetPath)
    gh release create $Version $assets --repo hkjang/dataworks --verify-tag --title "$Version - Data Works" --notes-file $notesPath
}

Remove-Item $notesPath -ErrorAction SilentlyContinue
// 저장소 루트의 package.json 이 받은 검증 스크립트를 web/ 에서 그대로 실행한다.
//
// `.github/workflows/ci.yml` 의 web 잡은 `defaults.run.working-directory: web` 에 의존해
// `npm ci`·`npm run lint`·`npm test`·`npm run build` 를 돌린다. 그래서 그 명령들을 CI 에서
// 뽑아 저장소 루트에서 돌리는 러너·릴리즈 자동화에게는 스크립트가 없는 것처럼 보였고,
// npm 이 상위 디렉터리로 올라가 저장소 밖의 package.json 을 프로젝트 루트로 집어
// `Missing script: "lint"` 로 exit 1 이 됐다(저장소 밖의 남의 스크립트가 실행될 수도 있다).
//
// 이 스크립트는 web 의 스크립트를 **완화 없이 그대로** 부르는 위임 계층이다. 검증 강도는
// web/package.json 과 web/eslint.config.js 에만 있고 여기서 플래그를 더하지 않는다.
//
// npm 은 run-script 의 PATH 앞에 상위 디렉터리의 node_modules/.bin 을 전부 붙이므로
// (web/scripts/run-with-supported-node.mjs 의 주석 참고) PATH 의 node·npm 을 믿지 않고
// npm 자신이 알려 준 경로(npm_execpath)와 현재 실행 중인 node(process.execPath)를 쓴다.
import { spawnSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const repoRoot = fileURLToPath(new URL('..', import.meta.url))
const webRoot = path.join(repoRoot, 'web')

// 허용 목록 — 루트에서 web 의 임의 스크립트를 돌릴 수 있게 열어 두지 않는다.
const ALLOWED = new Set(['lint', 'test', 'build'])

const script = process.argv[2]
if (!script || !ALLOWED.has(script)) {
  console.error(
    `usage: node scripts/web-run.mjs <${[...ALLOWED].join('|')}>\n` +
      `받은 값: ${script ?? '(없음)'}`,
  )
  process.exit(64)
}

// 이 스크립트 자신은 루트 package.json 의 `node scripts/web-run.mjs …` 로 불리므로
// 가로채인 PATH 의 node 로 돌고 있을 수 있다(실측: process.execPath 가 Node 20.19.2 심,
// npm_node_execpath 는 nvm 의 22.23.1). 그래서 자식 npm 에는 process.execPath 를 넘기지
// 않고 npm 자신이 돌고 있는 node 를 먼저 쓴다 — 그러지 않으면 구버전 node 가 web 의
// 스크립트까지 전파되어 web/scripts/run-with-supported-node.mjs 가 engines.node 하한
// 미달로 멈춘다(= web 테스트가 돌지 못한다).
const npmExecPath = process.env.npm_execpath
const nodeExecPath = process.env.npm_node_execpath || process.execPath

// npm 밖에서 직접 호출되면 PATH 의 npm 으로 폴백한다(그때는 node 도 PATH 의 것이다).
function runInWeb(args) {
  const spawned = npmExecPath
    ? spawnSync(nodeExecPath, [npmExecPath, ...args], { cwd: webRoot, stdio: 'inherit' })
    : spawnSync('npm', args, { cwd: webRoot, stdio: 'inherit', shell: true })
  if (spawned.error) {
    console.error(`npm ${args.join(' ')} 실행 실패: ${spawned.error.message}`)
    process.exit(1)
  }
  return spawned.status ?? 1
}

// 의존성이 없을 때만 설치한다. 매번 돌리면 검증이 몇 분씩 길어지고 lock 문제를 가린다.
// 설치 실패는 삼키지 않고 그 exit code 로 즉시 끝낸다 — CI 의 Install step 과 같은 명령이다.
if (!fs.existsSync(path.join(webRoot, 'node_modules'))) {
  const installStatus = runInWeb(['ci'])
  if (installStatus !== 0) process.exit(installStatus)
}

// cwd 를 web 으로 둔 채 web 의 스크립트를 부른다. 루트 cwd 에서 같은 이름을 다시 부르면
// 무한 재귀가 된다.
process.exit(runInWeb(['run', script]))
// npm 은 run-script 의 PATH 앞에 상위 디렉터리의 node_modules/.bin 을 전부 붙인다
// (프로젝트 → … → /home/<user> → /). 그 중 한 곳에 `node` 심링크가 있으면 그 node 가
// nvm·CI 의 node 를 가린 채 로컬 bin 의 `#!/usr/bin/env node` 를 받아, 툴체인이
// package.json 의 engines 보다 낮은 런타임에서 돈다. 실제로 그 상태에서는 jsdom 이
// 끌어오는 undici 가 로드 중 `webidl.util.markAsUncloneable is not a function` 으로
// 죽어서(Node 22.10 에서 추가된 worker_threads.markAsUncloneable 이 없다) jsdom 환경
// 테스트 파일이 전부 시작조차 못 하고 `npm test` 가 exit 1 이 됐다.
//
// 그래서 PATH 의 node 를 믿지 않고, npm 이 자기 자신을 돌리고 있는
// node(npm_node_execpath)로 로컬 bin 을 실행한다. npm 밖에서 직접 호출되면 이
// 스크립트를 띄운 node 를 쓴다. 어느 후보도 engines.node 하한을 넘기지 못하면
// 구버전에서 조용히 도는 대신 원인을 밝히고 멈춘다.
//
// 그 두 후보만으로는 부족한 경우가 둘 있고, 아래에서 각각 막는다.
//  (1) npm 자신이 이미 가로채인 구버전 node 로 떠 있으면 두 후보가 같은 구버전이라
//      하한을 넘기지 못한다(실측: `npx vitest` 로 들어오면 process.execPath 와
//      npm_node_execpath 가 모두 홈 디렉터리의 Node 20.19.2 심이 된다). 그래서
//      시스템에 설치된 node 들(nvm 버전 디렉터리 → /usr/local/bin → /usr/bin)까지
//      후보로 넓힌다. 상위 node_modules/.bin 은 문제의 근원이므로 후보에 넣지 않는다.
//  (2) 새 워크트리에는 web/node_modules 가 아예 없다. 예전에는 로컬 bin 의
//      package.json 을 그대로 readFileSync 해서 ENOENT 가 스택 트레이스와 함께
//      터지며 exit 1 로 죽었다(= 릴리즈 러너가 보던 그 exit 1). 이제 bin 이 없으면
//      고른 interpreter 로 `npm ci` 를 한 번 돌리고, 설치 실패는 그 종료 코드로
//      그대로 드러낸다. 이미 설치돼 있으면 아무 것도 설치하지 않는다.
import { spawnSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const webRoot = fileURLToPath(new URL('..', import.meta.url))

function readJson(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'))
}

function parseVersion(text) {
  const match = /(\d+)\.(\d+)\.(\d+)/.exec(String(text ?? ''))
  return match ? [Number(match[1]), Number(match[2]), Number(match[3])] : null
}

function meetsFloor(version, floor) {
  if (!floor) return true
  if (!version) return false
  for (let i = 0; i < 3; i += 1) {
    if (version[i] !== floor[i]) return version[i] > floor[i]
  }
  return true
}

function nodeVersionOf(execPath) {
  if (execPath === process.execPath) return parseVersion(process.versions.node)
  const probe = spawnSync(execPath, ['--version'], { encoding: 'utf8' })
  if (probe.error || probe.status !== 0) return null
  return parseVersion(probe.stdout)
}

// 설치돼 있지 않으면 빈 문자열 — 호출부가 설치를 돌린 뒤 다시 묻는다.
function resolveLocalBin(name) {
  const packageDir = path.join(webRoot, 'node_modules', name)
  const metaFile = path.join(packageDir, 'package.json')
  if (!fs.existsSync(metaFile)) return ''
  const meta = readJson(metaFile)
  const entry = typeof meta.bin === 'string' ? meta.bin : meta.bin?.[name]
  if (!entry) throw new Error(`${name} 패키지에 ${name} bin 항목이 없습니다`)
  return path.join(packageDir, entry)
}

function executable(file) {
  try {
    fs.accessSync(file, fs.constants.X_OK)
    return fs.statSync(file).isFile()
  } catch {
    return false
  }
}

// 시스템에 설치된 node 후보들. nvm 의 버전 디렉터리 + 흔한 설치 경로.
// 상위 node_modules/.bin 은 넣지 않는다 — 그게 애초에 이 스크립트가 있는 이유다.
function systemNodeCandidates() {
  const found = []
  const nvmDir = process.env.NVM_DIR
  if (nvmDir) {
    const base = path.join(nvmDir, 'versions', 'node')
    let entries = []
    try {
      entries = fs.readdirSync(base)
    } catch {
      entries = []
    }
    for (const name of entries) {
      if (parseVersion(name)) found.push(path.join(base, name, 'bin', 'node'))
    }
  }
  found.push('/usr/local/bin/node', '/usr/bin/node')
  return found.filter(executable)
}

function compareVersions(a, b) {
  for (let i = 0; i < 3; i += 1) {
    if (a[i] !== b[i]) return a[i] - b[i]
  }
  return 0
}

const [binName, ...args] = process.argv.slice(2)
if (!binName) {
  console.error('usage: node scripts/run-with-supported-node.mjs <local-bin> [args...]')
  process.exit(64)
}

const pkg = readJson(path.join(webRoot, 'package.json'))
const floor = parseVersion(pkg.engines?.node)

const seen = []
function probe(candidate) {
  const version = nodeVersionOf(candidate)
  seen.push(`${candidate} → ${version ? version.join('.') : '확인 불가'}`)
  return version
}

// 1) 운영자가 고른 node 를 먼저 존중한다 — npm 이 자기를 돌리는 node, 그 다음 이
//    스크립트를 띄운 node. 하한만 넘기면 그대로 쓴다.
let interpreter = ''
const preferred = [...new Set([process.env.npm_node_execpath, process.execPath].filter(Boolean))]
for (const candidate of preferred) {
  if (meetsFloor(probe(candidate), floor)) {
    interpreter = candidate
    break
  }
}

// 2) 둘 다 하한 미달이면(= npm 자신까지 구버전 node 에 가로채인 상태) 시스템에 설치된
//    node 중에서 고른다. 이때는 **하한을 넘기는 가장 낮은 버전**을 쓴다. 최신을 집으면
//    이 저장소가 한 번도 돌아 본 적 없는 런타임으로 검증이 넘어간다 — 실측으로 이
//    머신의 Node 25(25.0.0·25.9.0)에서는 src/features/auth/silent-sso.test.ts 가
//    깨지고 22.23.1·23.11.1 에서는 통과한다. engines.node 는 하한 선언이지 "최신을
//    쓰라" 는 뜻이 아니므로, 강요당해 고를 때는 가장 보수적인 쪽을 고른다.
if (!interpreter) {
  const usable = []
  for (const candidate of systemNodeCandidates()) {
    if (preferred.includes(candidate)) continue
    const version = probe(candidate)
    if (meetsFloor(version, floor)) usable.push({ candidate, version })
  }
  usable.sort((a, b) => compareVersions(a.version, b.version))
  interpreter = usable[0]?.candidate ?? ''
}

if (!interpreter) {
  console.error(
    `${binName} 을 실행할 수 있는 node 를 찾지 못했습니다. ` +
      `package.json 의 engines.node 는 ${pkg.engines?.node} 입니다.\n` +
      `확인한 후보:\n  ${seen.join('\n  ')}\n` +
      'npm 은 상위 디렉터리의 node_modules/.bin 을 PATH 앞에 붙이므로 ' +
      '거기에 설치된 구버전 node 가 PATH 를 가로챌 수 있습니다.',
  )
  process.exit(1)
}

// 로컬 bin 이 없으면 — 러너가 막 만든 워크트리다 — 고른 interpreter 로 한 번 설치한다.
let binPath = resolveLocalBin(binName)
if (!binPath) {
  console.error(
    `web/node_modules 에 ${binName} 이 없어 먼저 npm ci 를 돌립니다 (${path.join(webRoot, 'node_modules')}).`,
  )
  const npmExecPath = process.env.npm_execpath
  // npm 밖에서 직접 호출되면 PATH 의 npm 으로 폴백한다.
  const install = npmExecPath
    ? spawnSync(interpreter, [npmExecPath, 'ci'], { cwd: webRoot, stdio: 'inherit' })
    : spawnSync('npm', ['ci'], { cwd: webRoot, stdio: 'inherit', shell: true })
  if (install.error) {
